select d.id,d.name,d.category_id,d.price,d.image,d.description,d.status,d.update_time,c.name as category_name from setmeal d join category c on d.category_id = c.id


        and d.name like concat('%',#{name},'%')


        and d.category_id=#{categoryId}


        and d.status=#{status}


order by category_id desc limit #{start},#{pageSize}

select * from setmeal


        and name like concat('%',#{name},'%')


        and category_id = #{categoryId}


        and status = #{status}
